  /* just verify that it's a socket */
  addr_len = sizeof(ss2);
  if (getsockname(new_fd, (struct sockaddr *)&ss2, &addr_len) == -1) {
    memprintf(err, "cannot use file descriptor '%d' : %s.", new_fd, strerror(errno));
    goto out;
